\u3000\u3000\u600E\u6837\u624D\u80FD\u505A\u5230\u5462\uFF1F\u9996\u5148\uFF0C\u6211\u8981\u4E3A\u6BCF\u4E00\u5929\uFF0C\u6BCF\u4E2A\u661F\u671F\u3001\u6BCF\u4E2A\u6708\u3002\u6BCF\u4E00\u5E74\u3001\u751A\u81F3\u6211\u7684\u4E00\u751F\u786E\u7ACB\u76EE\u6807\u3002\u6B63\u50CF\u79CD\u5B50\u9700\u8981\u96E8\u6C34\u7684\u6ECB\u6DA6\u624D\u80FD\u7834\u571F\u800C\u51FA\uFF0C\u53D1\u82BD\u957F\u53F6\uFF0C\u6211\u7684\u751F\u547D\u4E5F\u987B\u6709\u76EE\u7684\u65B9\u80FD\u7ED3\u51FA\u7855\u679C\u3002\u5728\u5236\u5B9A\u76EE\u6807\u7684\u65F6\u5019\uFF0C\u4E0D\u59A8\u53C2\u8003\u8FC7\u53BB\u6700\u597D\u7684\u6210\u7EE9\uFF0C\u4F7F\u5176\u53D1\u626C\u5149\u5927\u3002\u8FD9\u5FC5\u987B\u6210\u4E3A\u6211\u672A\u6765\u751F\u6D3B\u7684\u76EE\u6807\u3002\u6C38\u8FDC\u4E0D\u8981\u5F53\u5FC3\u76EE\u6807\u8FC7\u9AD8\u3002\u53D6\u6CD5\u4E4E\u4E0A\uFF0C\u5F97\u5176\u4E2D\u4E5F\uFF0C\u53D6\u6CD5\u4E2D\u4E5F\uFF0C\u5F97\u5176\u4E0B\u4E5F\u3002

